# Win-stay/lose-shift on ORL variant: observed vs generated by fitted ORL variant.
source("scripts/10_orl_variant.R")
results_orl_wl <- readRDS("output/orl_wl_fit_horstmann.rds")
deck_outcomes <- list(net_h[choice_h == 1], net_h[choice_h == 2],
                      net_h[choice_h == 3], net_h[choice_h == 4])

# WSLS for one sequence: P(stay | gain) - P(stay | loss)
wsls_of <- function(choice, outcome) {
  n <- length(choice)
  stay <- choice[-1] == choice[-n]
  gain <- outcome[-n] >= 0
  mean(stay[gain]) - mean(stay[!gain])
}

# Observed
wsls_obs <- rep(NA, nrow(choice_h))
for (i in 1:nrow(choice_h)) wsls_obs[i] <- wsls_of(choice_h[i, ], net_h[i, ])

# Generated: 20 simulations per person from their fitted ORL variant parameters
est_wl <- as.matrix(results_orl_wl[, c("Arew", "Apun", "Kprime", "betaF", "betaPw", "betaPl")])
wsls_sim_wl <- rep(NA, nrow(est_wl))
set.seed(2026)
for (i in 1:nrow(est_wl)) {
  vals <- rep(NA, 20)
  for (r in 1:20) {
    s <- sim_orl_wl(est_wl[i, ], deck_outcomes)
    vals[r] <- wsls_of(s$choice, s$outcome)
  }
  wsls_sim_wl[i] <- mean(vals, na.rm = TRUE)
}

summary(wsls_obs)
summary(wsls_sim_wl)
cor(wsls_obs, wsls_sim_wl, use = "complete.obs")

t.test(wsls_obs, wsls_sim_wl, paired = TRUE)
mean(wsls_obs > wsls_sim_wl, na.rm = TRUE)










